import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as t,o as s,af as n}from"./chunks/mermaid.DrCHRkU0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"How I Use Claude Code","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tech/agent/how-i-use-claude-code.md","filePath":"zh/tech/agent/how-i-use-claude-code.md","lastUpdated":1780928608000}'),o={name:"zh/tech/agent/how-i-use-claude-code.md"};function i(l,e,d,r,p,h){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="how-i-use-claude-code" tabindex="-1">How I Use Claude Code <a class="header-anchor" href="#how-i-use-claude-code" aria-label="Permalink to &quot;How I Use Claude Code&quot;">​</a></h1><blockquote><p>原文: <a href="https://boristane.com/blog/how-i-use-claude-code/" target="_blank" rel="noreferrer">https://boristane.com/blog/how-i-use-claude-code/</a></p></blockquote><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>作者 Boris Trompad 使用 Claude Code 作为主要开发工具约 9 个月，形成了一套与大多数 AI 编程工具使用者截然不同的工作流。</p><p><strong>核心原则</strong>: 在你审查并批准书面计划之前，永远不要让 Claude 写代码。这种&quot;计划与执行分离&quot;是整个工作流中最重要的原则。</p><h2 id="整体工作流" tabindex="-1">整体工作流 <a class="header-anchor" href="#整体工作流" aria-label="Permalink to &quot;整体工作流&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Research → Plan → Annotate (循环 1-6 次) → Todo List → Implement → Feedback &amp; Iterate</span></span></code></pre></div><h2 id="phase-1-research-研究阶段" tabindex="-1">Phase 1: Research（研究阶段） <a class="header-anchor" href="#phase-1-research-研究阶段" aria-label="Permalink to &quot;Phase 1: Research（研究阶段）&quot;">​</a></h2><p>每个有意义的任务都从深度阅读指令开始。让 Claude 在做任何事情之前彻底理解代码库的相关部分，并且要求将发现写入持久化的 markdown 文件，而非仅在对话中口头总结。</p><h3 id="典型指令示例" tabindex="-1">典型指令示例 <a class="header-anchor" href="#典型指令示例" aria-label="Permalink to &quot;典型指令示例&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>read this folder in depth, understand how it works deeply, what it does and all its specificities. when that&#39;s done, write a detailed report of your learnings and findings in research.md</span></span>
<span class="line"><span></span></span>
<span class="line"><span>study the notification system in great details, understand the intricacies of it and write a detailed research.md document with everything there is to know about how notifications work</span></span>
<span class="line"><span></span></span>
<span class="line"><span>go through the task scheduling flow, understand it deeply and look for potential bugs. there definitely are bugs in the system as it sometimes runs tasks that should have been cancelled. keep researching the flow until you find all the bugs, don&#39;t stop until all the bugs are found. when you&#39;re done, write a detailed report of your findings in research.md</span></span></code></pre></div><h3 id="关键技巧" tabindex="-1">关键技巧 <a class="header-anchor" href="#关键技巧" aria-label="Permalink to &quot;关键技巧&quot;">​</a></h3><p>注意 &quot;deeply&quot;、&quot;in great details&quot;、&quot;intricacies&quot;、&quot;go through everything&quot; 这些词。没有这些词，Claude 会泛读——读一个文件、看到函数签名级别的说明就跳过。你需要明确传递&quot;不接受浅层阅读&quot;的信号。</p><h3 id="为什么-artifact-research-md-很关键" tabindex="-1">为什么 artifact（research.md）很关键 <a class="header-anchor" href="#为什么-artifact-research-md-很关键" aria-label="Permalink to &quot;为什么 artifact（research.md）很关键&quot;">​</a></h3><p>这不是让 Claude 做作业，而是<strong>作者的审查面（review surface）</strong>。可以阅读验证 Claude 是否真正理解了系统，在任何规划发生之前纠正误解。如果研究错了，计划就会错，实现就会错。<strong>Garbage in, garbage out。</strong></p><p>这是 AI 辅助编程中最昂贵的失败模式，不是语法错误或逻辑错误，而是孤立工作但在周围系统中造成破坏的实现。</p><h2 id="phase-2-planning-规划阶段" tabindex="-1">Phase 2: Planning（规划阶段） <a class="header-anchor" href="#phase-2-planning-规划阶段" aria-label="Permalink to &quot;Phase 2: Planning（规划阶段）&quot;">​</a></h2><p>研究被审查后，再请求详细的实施计划，写入单独的 markdown 文件。</p><h3 id="典型指令示例-1" tabindex="-1">典型指令示例 <a class="header-anchor" href="#典型指令示例-1" aria-label="Permalink to &quot;典型指令示例&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I want to build a new feature &lt;name and description&gt; that extends the system to perform &lt;business outcome&gt;. write a detailed plan.md document outlining how to implement this. include code snippets</span></span>
<span class="line"><span></span></span>
<span class="line"><span>the list endpoint should support cursor-based pagination instead of offset. write a detailed plan.md for how to achieve this. read source files before suggesting changes, base the plan on the actual codebase</span></span></code></pre></div><p>生成的计划总是包括：</p><ul><li>方法的详细解释</li><li>显示实际更改的代码片段</li><li>将被修改的文件路径</li><li>考虑因素和权衡</li></ul><h3 id="使用自己的-md-计划文件而非-claude-code-内置的-plan-mode" tabindex="-1">使用自己的 .md 计划文件而非 Claude Code 内置的 plan mode <a class="header-anchor" href="#使用自己的-md-计划文件而非-claude-code-内置的-plan-mode" aria-label="Permalink to &quot;使用自己的 .md 计划文件而非 Claude Code 内置的 plan mode&quot;">​</a></h3><p>内置 plan mode 不够好。Markdown 文件给你完全控制权，可以在编辑器中编辑、添加内联注释，并作为真实 artifact 持久化在项目中。</p><h3 id="实用技巧" tabindex="-1">实用技巧 <a class="header-anchor" href="#实用技巧" aria-label="Permalink to &quot;实用技巧&quot;">​</a></h3><p>对于范围明确的 feature，如果在开源仓库中见过好的实现，会把那段代码作为参考一起分享：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>this is how they do sortable IDs, write a plan.md explaining how we can adopt a similar approach.</span></span></code></pre></div><p>Claude 有具体参考实现时工作效果显著更好。</p><h2 id="the-annotation-cycle-注释循环" tabindex="-1">The Annotation Cycle（注释循环） <a class="header-anchor" href="#the-annotation-cycle-注释循环" aria-label="Permalink to &quot;The Annotation Cycle（注释循环）&quot;">​</a></h2><p>这是工作流中最独特的部分，也是添加最多价值的部分。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Claude 写 plan.md → 在编辑器中审查 → 添加内联注释 → 发回给 Claude → Claude 更新计划</span></span>
<span class="line"><span>循环直到满意 → 请求 Todo List</span></span></code></pre></div><h3 id="如何注释" tabindex="-1">如何注释 <a class="header-anchor" href="#如何注释" aria-label="Permalink to &quot;如何注释&quot;">​</a></h3><p>打开 Claude 写的计划文档，直接在内联添加注释。注释纠正错误假设、拒绝方案、添加约束或提供 Claude 没有的领域知识。</p><h3 id="真实注释示例" tabindex="-1">真实注释示例 <a class="header-anchor" href="#真实注释示例" aria-label="Permalink to &quot;真实注释示例&quot;">​</a></h3><ul><li><code>&quot;use drizzle:generate for migrations, not raw SQL&quot;</code> — Claude 没有的领域知识</li><li><code>&quot;no — this should be a PATCH, not a PUT&quot;</code> — 纠正错误假设</li><li><code>&quot;remove this section entirely, we don&#39;t need caching here&quot;</code> — 拒绝提议的方案</li><li><code>&quot;the queue consumer already handles retries, so this retry logic is redundant. remove it and just let it fail&quot;</code> — 解释为什么应该改动</li><li><code>&quot;this is wrong, the visibility field needs to be on the list itself, not on individual items&quot;</code> — 重定向整个计划部分</li></ul><h3 id="关键指令" tabindex="-1">关键指令 <a class="header-anchor" href="#关键指令" aria-label="Permalink to &quot;关键指令&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I added a few notes to the document, address all the notes and update the document accordingly. don&#39;t implement yet</span></span></code></pre></div><p>这个循环重复 1-6 次。明确的 &quot;don&#39;t implement yet&quot; 是必不可少的——没有它，Claude 会认为计划够好时就跳到写代码。</p><h3 id="为什么注释循环效果这么好" tabindex="-1">为什么注释循环效果这么好 <a class="header-anchor" href="#为什么注释循环效果这么好" aria-label="Permalink to &quot;为什么注释循环效果这么好&quot;">​</a></h3><p>Markdown 文件充当你和 Claude 之间的<strong>共享可变状态</strong>。可以按自己的节奏思考、准确标注问题所在、重新投入而不丢失上下文。不需要试图在聊天消息中解释一切——只需指向文档中问题的确切位置并在那里写上修正。</p><h2 id="the-todo-list-任务清单" tabindex="-1">The Todo List（任务清单） <a class="header-anchor" href="#the-todo-list-任务清单" aria-label="Permalink to &quot;The Todo List（任务清单）&quot;">​</a></h2><p>在实施开始前，总是请求细粒度的任务分解：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add a detailed todo list to the plan, with all the phases and individual tasks necessary to complete the plan - don&#39;t implement yet</span></span></code></pre></div><p>这创建了一个清单，在实施过程中作为进度追踪器。Claude 逐项标记为完成，随时可以看计划文件了解进度。</p><h2 id="phase-3-implementation-实施阶段" tabindex="-1">Phase 3: Implementation（实施阶段） <a class="header-anchor" href="#phase-3-implementation-实施阶段" aria-label="Permalink to &quot;Phase 3: Implementation（实施阶段）&quot;">​</a></h2><p>计划就绪后，发出实施命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>implement it all. when you&#39;re done with a task or phase, mark it as completed in the plan document. do not stop until all tasks and phases are completed. do not add unnecessary comments or jsdocs, do not use any or unknown types. continuously run typecheck to make sure you&#39;re not introducing new issues.</span></span></code></pre></div><p>这个单一 prompt 编码了所有重要事项：</p><table tabindex="0"><thead><tr><th>指令</th><th>含义</th></tr></thead><tbody><tr><td><code>implement it all</code></td><td>执行计划中的一切，不要挑着做</td></tr><tr><td><code>mark it as completed in the plan document</code></td><td>计划是进度的真实来源</td></tr><tr><td><code>do not stop until all tasks and phases are completed</code></td><td>不要在流程中间暂停等确认</td></tr><tr><td><code>do not add unnecessary comments or jsdocs</code></td><td>保持代码整洁</td></tr><tr><td><code>do not use any or unknown types</code></td><td>保持严格类型</td></tr><tr><td><code>continuously run typecheck</code></td><td>及早发现问题，不要等到最后</td></tr></tbody></table><p>当说 &quot;implement it all&quot; 时，所有决策都已做出并验证过。实施变成机械的而非创造性的。<strong>实施应该是无聊的。创造性工作发生在注释循环中。</strong></p><h2 id="实施过程中的反馈" tabindex="-1">实施过程中的反馈 <a class="header-anchor" href="#实施过程中的反馈" aria-label="Permalink to &quot;实施过程中的反馈&quot;">​</a></h2><p>Claude 执行计划时，角色从架构师转为监督者。Prompt 变得简短得多。</p><p>规划阶段的注释可能是一段，实施阶段的修正通常只是一句话：</p><ul><li><code>&quot;You didn&#39;t implement the deduplicateByTitle function.&quot;</code></li><li><code>&quot;You built the settings page in the main app when it should be in the admin app, move it.&quot;</code></li></ul><h3 id="前端工作的特殊性" tabindex="-1">前端工作的特殊性 <a class="header-anchor" href="#前端工作的特殊性" aria-label="Permalink to &quot;前端工作的特殊性&quot;">​</a></h3><p>前端工作迭代最多。在浏览器中测试，然后快速修正：</p><ul><li><code>&quot;wider&quot;</code></li><li><code>&quot;still cropped&quot;</code></li><li><code>&quot;there&#39;s a 2px gap&quot;</code></li></ul><p>对于视觉问题，有时附上截图。截图比描述更快传达问题。</p><h3 id="参考现有代码" tabindex="-1">参考现有代码 <a class="header-anchor" href="#参考现有代码" aria-label="Permalink to &quot;参考现有代码&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>this table should look exactly like the users table, same header, same pagination, same row density.</span></span></code></pre></div><p>指向参考比从头描述设计精确得多。大多数成熟代码库中的 feature 都是现有模式的变体。</p><h3 id="回退和重新-scoping" tabindex="-1">回退和重新 scoping <a class="header-anchor" href="#回退和重新-scoping" aria-label="Permalink to &quot;回退和重新 scoping&quot;">​</a></h3><p>当某事走向错误方向时，不试图打补丁，而是回退：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I reverted everything. Now all I want is to make the list view more minimal — nothing else.</span></span></code></pre></div><p>回退后缩小范围几乎总是比逐步修复糟糕的方案产生更好的结果。</p><h2 id="保持主动控制" tabindex="-1">保持主动控制 <a class="header-anchor" href="#保持主动控制" aria-label="Permalink to &quot;保持主动控制&quot;">​</a></h2><p>即使把实施委托给 Claude，也从不给它对构建内容的完全自主权。绝大多数主动 steering 在 plan.md 文档中完成。</p><h3 id="对提案的评估" tabindex="-1">对提案的评估 <a class="header-anchor" href="#对提案的评估" aria-label="Permalink to &quot;对提案的评估&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Claude 提议变更 → 逐项评估</span></span>
<span class="line"><span>- 接受原样</span></span>
<span class="line"><span>- 修改方法</span></span>
<span class="line"><span>- 跳过/删除</span></span>
<span class="line"><span>- 覆盖技术选择</span></span></code></pre></div><p><strong>Cherry-picking 提案</strong>: &quot;第一个用 Promise.all，不要过度复杂；第三个提取为独立函数；忽略第四和第五个，它们不值得那么复杂。&quot;</p><p><strong>修剪范围</strong>: 当计划包含 nice-to-have 时，主动削减。</p><p><strong>保护现有接口</strong>: &quot;这三个函数的签名不应该变，调用者应该适应，不是库。&quot;</p><p><strong>覆盖技术选择</strong>: &quot;用这个模型而不是那个。&quot;</p><h2 id="single-long-sessions-单一长会话" tabindex="-1">Single Long Sessions（单一长会话） <a class="header-anchor" href="#single-long-sessions-单一长会话" aria-label="Permalink to &quot;Single Long Sessions（单一长会话）&quot;">​</a></h2><p>研究、规划和实施都在一个单一长会话中运行，而非分成多个会话。一个会话可能从深度阅读文件夹开始，经历三轮计划注释，然后运行完整实施，全部在一个连续对话中。</p><p>在 50% 上下文窗口后没有看到大家谈论的性能下降。实际上，当说 &quot;implement it all&quot; 时，Claude 已经花了整个会话来构建理解。</p><p>当上下文窗口满了，Claude 的自动压缩维持足够上下文继续运行。而计划文档作为持久化 artifact 以完整保真度存活。</p><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><blockquote><p>Read deeply, write a plan, annotate the plan until it&#39;s right, then let Claude execute the whole thing without stopping, checking types along the way.</p></blockquote><p>没有魔法 prompt，没有复杂的系统指令，没有花哨的 hack。只有一条纪律严明的管道，把思考和打字分开。</p><h2 id="补充资源" tabindex="-1">补充资源 <a class="header-anchor" href="#补充资源" aria-label="Permalink to &quot;补充资源&quot;">​</a></h2><ul><li><a href="https://nominal.dev" target="_blank" rel="noreferrer">Nominal.dev</a> — 作者正在做的项目</li></ul>`,82)])])}const q=a(o,[["render",i]]);export{b as __pageData,q as default};
